export interface ConnectorConfig {
  linearApiToken: string
  discordBotToken: string
  discordChannelId: string
  fetch?: typeof fetch
}

export interface LinearWebhookPayload {
  action: string
  type: string
  actor: {
    id: string
    type: string
    name: string
    email: string
    url: string
  }
  data: {
    id: string
    state: {
      name: string
    }
    title: string
    url: string
    createdAt: string
    updatedAt: string
  }
  url: string
  createdAt: string
  webhookTimestamp: number
}

export interface LinearComment {
  author: {
    name: string
  }
  content: string
  createdAt: string
}

export interface LinearCommentsResponse {
  issue: {
    comments: {
      nodes: LinearComment[]
      pageInfo: {
        hasNextPage: boolean
        endCursor: string | null
      }
    }
  }
}

export interface GraphQLResponse<T> {
  data?: T
  errors?: Array<{ message: string }>
}

export interface DiscordMessageResponse {
  id: string
  channel_id: string
  content: string
  timestamp: string
}

export interface HandleResult {
  discordMessageId: string
  commentCount: number
}

async function fetchAllComments(
  issueId: string,
  linearApiToken: string,
  fetchFn: typeof fetch,
): Promise<LinearComment[]> {
  const allComments: LinearComment[] = []
  let cursor: string | null = null
  let hasNextPage = true

  while (hasNextPage) {
    const query = `
      query GetIssueComments($issueId: ID!, $cursor: String) {
        issue(id: $issueId) {
          comments(first: 100, after: $cursor) {
            nodes {
              author { name }
              content
              createdAt
            }
            pageInfo {
              hasNextPage
              endCursor
            }
          }
        }
      }
    `

    const variables: Record<string, unknown> = { issueId }
    if (cursor) variables.cursor = cursor

    const response = await fetchFn('https://api.linear.app/graphql', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${linearApiToken}`,
      },
      body: JSON.stringify({ query, variables }),
    })

    if (!response.ok) {
      throw new Error(`Linear GraphQL request failed: ${response.status} ${response.statusText} at https://api.linear.app/graphql`)
    }

    const result = (await response.json()) as GraphQLResponse<LinearCommentsResponse>

    if (result.errors && result.errors.length > 0) {
      throw new Error(`Linear GraphQL errors: ${result.errors.map((e) => e.message).join(', ')}`)
    }

    if (!result.data?.issue?.comments) {
      throw new Error('Unexpected Linear GraphQL response structure: missing issue.comments')
    }

    const { nodes, pageInfo } = result.data.issue.comments
    allComments.push(...nodes)
    hasNextPage = pageInfo.hasNextPage
    cursor = pageInfo.endCursor
  }

  return allComments
}

function formatDigest(issueTitle: string, comments: LinearComment[]): string {
  if (comments.length === 0) {
    return `Issue Closed: ${issueTitle}\n\nNo comments.`
  }

  const commentLines = comments.map(
    (c) => `- ${c.author.name} (${c.createdAt}): ${c.content}`,
  )
  return `Issue Closed: ${issueTitle}\n\nComments:\n${commentLines.join('\n')}`
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (payload.action !== 'update' || payload.type !== 'Issue') {
    throw new Error('Payload is not an issue update webhook')
  }

  if (payload.data.state.name !== 'Closed') {
    throw new Error('Issue state is not Closed')
  }

  const issueId = payload.data.id
  const issueTitle = payload.data.title

  if (!issueId) {
    throw new Error('Missing required field: data.id')
  }
  if (!issueTitle) {
    throw new Error('Missing required field: data.title')
  }

  const comments = await fetchAllComments(issueId, config.linearApiToken, fetchFn)

  const content = formatDigest(issueTitle, comments)

  if (content.length > 2000) {
    throw new Error(`Formatted digest exceeds Discord's 2000 character limit (${content.length} chars)`)
  }

  const discordUrl = `https://discord.com/api/v10/channels/${config.discordChannelId}/messages`
  const discordResponse = await fetchFn(discordUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bot ${config.discordBotToken}`,
    },
    body: JSON.stringify({ content }),
  })

  if (!discordResponse.ok) {
    throw new Error(`Discord API request failed: ${discordResponse.status} ${discordResponse.statusText} at ${discordUrl}`)
  }

  const message = (await discordResponse.json()) as DiscordMessageResponse

  return {
    discordMessageId: message.id,
    commentCount: comments.length,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, LinearWebhookPayload, ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      linearApiToken: 'test-linear-token',
      discordBotToken: 'test-discord-token',
      discordChannelId: '987654321098765432',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.discordMessageId).toBe('123456789012345678')
    expect(result.commentCount).toBe(0)
  })
})

describe('handle', () => {
  it('fetches comments via cursor pagination and posts to Discord', async () => {
    const commentsPage1 = [
      { author: { name: 'Alice' }, content: 'Thanks for fixing this!', createdAt: '2020-01-23T12:55:00.000Z' },
      { author: { name: 'Bob' }, content: 'Looks good to me.', createdAt: '2020-01-23T12:57:00.000Z' },
    ]
    const commentsPage2 = [
      { author: { name: 'Carol' }, content: 'Ship it!', createdAt: '2020-01-23T13:00:00.000Z' },
    ]

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql' && req.method === 'POST') {
        const body = req.json as { variables?: { cursor?: string } }
        const isFirstPage = !body.variables?.cursor
        if (isFirstPage) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: commentsPage1,
                  pageInfo: { hasNextPage: true, endCursor: 'cursor-123' },
                },
              },
            },
          })
        }
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: commentsPage2,
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        })
      }
      if (req.url === 'https://discord.com/api/v10/channels/987654321098765432/messages' && req.method === 'POST') {
        return jsonResponse(
          {
            id: '123456789012345678',
            channel_id: '987654321098765432',
            content: req.json?.content,
            timestamp: '2020-01-23T13:00:00.000Z',
          },
          201,
        )
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, id: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9', title: 'Fix login bug' },
    }

    const result = await handle(payload, {
      linearApiToken: 'linear-token',
      discordBotToken: 'discord-token',
      discordChannelId: '987654321098765432',
      fetch,
    })

    expect(result.discordMessageId).toBe('123456789012345678')
    expect(result.commentCount).toBe(3)

    const graphqlCalls = calls.filter((c) => c.url === 'https://api.linear.app/graphql')
    expect(graphqlCalls.length).toBe(2)
    expect(graphqlCalls[0].json).toMatchObject({
      query: expect.stringContaining('GetIssueComments'),
      variables: { issueId: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9' },
    })
    expect(graphqlCalls[1].json).toMatchObject({
      variables: { issueId: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9', cursor: 'cursor-123' },
    })

    const discordCall = calls.find((c) => c.url.includes('discord.com'))
    expect(discordCall).toBeDefined()
    expect(discordCall!.headers.get('authorization')).toBe('Bot discord-token')
    expect(discordCall!.json).toMatchObject({
      content: expect.stringContaining('Issue Closed: Fix login bug'),
    })
    expect(discordCall!.json).toMatchObject({
      content: expect.stringContaining('Alice (2020-01-23T12:55:00.000Z): Thanks for fixing this!'),
    })
    expect(discordCall!.json).toMatchObject({
      content: expect.stringContaining('Carol (2020-01-23T13:00:00.000Z): Ship it!'),
    })
  })

  it('throws when required field data.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, id: '' } }
    await expect(handle(payload as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Missing required field: data.id')
  })

  it('throws when required field data.title is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, title: '' } }
    await expect(handle(payload as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Missing required field: data.title')
  })

  it('throws when issue state is not Closed', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, state: { name: 'Open' } } }
    await expect(handle(payload as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Issue state is not Closed')
  })

  it('throws on non-2xx Linear GraphQL response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ error: 'unauthorized' }, 401)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(SOURCE_EXAMPLE as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Linear GraphQL request failed: 401 Unauthorized at https://api.linear.app/graphql')

    expect(calls.length).toBe(1)
  })

  it('throws on Linear GraphQL errors field', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ errors: [{ message: 'Field not found' }] }, 200)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(SOURCE_EXAMPLE as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Linear GraphQL errors: Field not found')
  })

  it('throws on non-2xx Discord response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: { issue: { comments: { nodes: [], pageInfo: { hasNextPage: false, endCursor: null } } } },
        })
      }
      if (req.url.includes('discord.com')) {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(SOURCE_EXAMPLE as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow('Discord API request failed: 401 Unauthorized at https://discord.com/api/v10/channels/t/messages')

    expect(calls.length).toBe(2)
  })

  it('throws when digest exceeds 2000 characters', async () => {
    const manyComments = Array.from({ length: 100 }, (_, i) => ({
      author: { name: `User${i}` },
      content: 'x'.repeat(25),
      createdAt: '2020-01-23T12:55:00.000Z',
    }))

    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: manyComments,
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        })
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(SOURCE_EXAMPLE as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: 't',
      fetch,
    })).rejects.toThrow("exceeds Discord's 2000 character limit")
  })

  it('handles zero comments gracefully', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: [],
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        })
      }
      if (req.url.includes('discord.com')) {
        return jsonResponse(
          {
            id: 'msg-1',
            channel_id: '987654321098765432',
            content: 'Issue Closed: Fix login bug\n\nNo comments.',
            timestamp: '2020-01-23T13:00:00.000Z',
          },
          201,
        )
      }
      return jsonResponse({}, 200)
    })

    const result = await handle(SOURCE_EXAMPLE as LinearWebhookPayload, {
      linearApiToken: 't',
      discordBotToken: 't',
      discordChannelId: '987654321098765432',
      fetch,
    })

    expect(result.commentCount).toBe(0)
    expect(result.discordMessageId).toBe('msg-1')

    const discordCall = calls.find((c) => c.url.includes('discord.com'))
    expect(discordCall!.json).toMatchObject({
      content: 'Issue Closed: Fix login bug\n\nNo comments.',
    })
  })
})

